"""Read existing evidence and refresh only this process-audit's harness.json."""
import hashlib,json,re
from pathlib import Path
ROOT=Path(__file__).resolve().parents[3]
OUT=Path(__file__).with_suffix('.json')
def pin(rel):
 p=ROOT/rel
 return {'path':rel,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
def artifact(job,name):
 return next((ROOT/'results/proj-rsi/scheduler/artifacts'/job).rglob(name))
def rel(p):return str(p.relative_to(ROOT))
def evidence(*paths):return [pin(p) for p in paths]
rows=[]
for job,label,diagnosis,miss,review in [
 ('pw41.ticket.narrow.01','PW41 setup','Harness classified every RQ TU as containing four M128 EH/control targets; actual small TU correctly has none.','95/99 SASS/resource checks, eleven CPU tests and independent review missed actual small/large module partition.','proj_rsi/scheduling/reviews/pw41-ticket-01.md'),
 ('pw44.stack.fullscope.01','PW44 resource gate','Harness required Runtime user static shared=1024, conflating dump SHARED/system reservation. Exact failed flag/value was not persisted and remains unknown.','123-pin independent wrapper review, fake complete mechanism run and physical/resource tests accepted the incorrect expected value.','proj_rsi/audits/pw44-stack-lab-independent.md'),
 ('research.moe.ss.stage.screen.v2.01','MoE SS v2 resource gate','Same static-shared conflation: actual T8/DIV8 runtime static_shared0, registers32, local0, maxThreads256, maxDynamic49152, occupancy8.','82-input screen, eleven CPU tests, 4064 normative bit cases, eight full production stream/physical checks and review still encoded static1024.','proj_rsi/scheduling/reviews/moe-ss-stage-screen-v2-01.md')]:
 p=artifact(job,'result.json');d=json.loads(p.read_text());inv=artifact(job,'inventory.json');ii=json.loads(inv.read_text())
 logs=list(inv.parent.rglob('*.host.log'));dates=[]
 for log in logs:dates+=re.findall(r'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ',log.read_text())
 row={'case':label,'classification':'HARNESS_SETUP_FAILURE_NO_CANDIDATE_NUMERIC_FAILURE_ESTABLISHED','cause':diagnosis,'CPU_review_blind_spot':miss,'result_state':d['state'],'measured_trial_checks':len(d.get('checks',[])),'measured_trial_raw_samples':len(d.get('raw',[])),'source_pins_at_dispatch':len(ii['dispatch']['source_pins']),'evidence':evidence(rel(p),rel(inv),review),'host_log_timestamp_endpoints':dates}
 if 'started_at'in d and 'finished_at'in d:row['result_wall_seconds']=d['finished_at']-d['started_at']
 if label.startswith('MoE'):row['compile_seconds']=d['cost']['compile_seconds']
 rows.append(row)
p=artifact('pw38.hotpath.trace.01','capture.json');d=json.loads(p.read_text());tr=d['trace_cases'];assert len(tr)==1
first=next(iter(tr.values()));assert 'profile_terminal'in first
rows.append({'case':'PW38 trace01 annotation collision','classification':'PARSER_INSTRUMENTATION_FAILURE_CURRENT_PROFILE_TERMINAL_PASSED','cause':'CPU user_annotation and gpu_user_annotation legitimately share replay names; parser failed to filter category and rejected duplicate scopes.','CPU_review_blind_spot':'136 dependency pins, twelve author parser negatives and six independent parser/counter negatives omitted this genuine trace category collision.','current_trace_cases_before_failure':len(tr),'current_cold_event_samples_first_case':len(first['benchmarks']),'profile_replays_first_case':first['profile_replays'],'host_wall_seconds':71,'evidence':evidence(rel(p),'proj_rsi/scheduling/validations/pw38-hotpath-trace-01.json','proj_rsi/audits/pw38-hotpath-trace-independent.md')})
rows.append({'case':'GV prepared cache lifetime','classification':'HARNESS_DEFECT_CAUGHT_CPU_BEFORE_GPU_ADMISSION','cause':'Production prepare removes gvc12; fixed mechanism required it after prepare. Immutable revision2 would always abort at fixed stage.','CPU_review_blind_spot':'203 closure pins, offline15+8 exact device streams, scalar/chain/source proofs and fake terminal/counter negatives do not model prepared-state lifetime. Independent source-flow review caught it before driver GO.','GPU_cost_incurred_by_this_blocker_seconds':0,'evidence':evidence('proj_rsi/candidates/gv_predxor_trial/history/v2-missing-prepared-packs/manifest.json','proj_rsi/candidates/gv_predxor_trial/history/v2-missing-prepared-packs/mechanism.py','proj_rsi/candidates/gv_predxor_trial/history/v2-missing-prepared-packs/cpu-proof.json','proj_rsi/candidates/pw45/submission.py','proj_rsi/audits/gv-predxor-lab-v2-blocker.md')})
report={'scope':'CPU/read-only historical process audit; writes harness.* only; no GPU/SSH/API/queue/git mutations','finding':'All five requested failures are harness/instrumentation defects, not established candidate numeric kernel failures. This selected sample is not a population failure-rate estimate.','timing_limits':'Result start/finish and external host timestamp spans are different accounting scopes; do not sum or call them GPU busy time. CPU budgets in reviews are estimates, not measured CPU usage.','cases':rows,'reuse_final_evidence':evidence('proj_rsi/audits/pw44-stack-02-independent/report.md','proj_rsi/audits/pw41-ticket-repair-independent.md','proj_rsi/scheduling/reviews/pw44-stack-02.md'),'recommendations':[
 {'gate':'Source/build identity','early':'One candidate/control source+build recipe digest, exact measured symbol and shape. Reuse validated unchanged binary by SO hash/compiler/flags/architecture.','defer_or_remove':'No unconditional re-review/redump of every unrelated old main or transitive history file for each screen.','final':'Validate newly built/touched/served functions; full closure and independent final result review before promotion.'},
 {'gate':'Resource queries','early':'One launch helper shared across experiments; persist raw actual fields before assertions. Check actual requested threads/dynamic bytes, capacity, launch success and nonzero occupancy for measured functions. Keep user static and driver reservation typed separately.','defer_or_remove':'Remove dump SHARED==Runtime sharedSizeBytes assertion. Resource maxima alone do not justify rejection without correctness/safety/performance purpose.','final':'Reconcile full served scope; exact resource matching only when claiming binary identity or matched resources.'},
 {'gate':'Harness integration','early':'Small real-shape/module/state fixture: actual TU dispatch subset, completed prepare cache lifetime, real trace categories. Prefer one bounded GPU smoke after minimal source safety review over more self-consistent fake mocks.','defer_or_remove':'Stop treating test/pin counts as integration evidence; do not duplicate fake models that copy expected constants.','final':'Reusable regression fixtures for observed failure classes.'},
 {'gate':'Numerics/basis','early':'Independent normal/outlier/zero plus discriminating current-X/boundary/changed-index probes for each measured path; terminal output before any further replay; poison outputs; active counter/immutability checks.','defer_or_remove':'Defer repeated allK for every arm/geometry and all30 policy/full-task campaigns until measured mechanism warrants integration; reuse unchanged mapping proofs. No arbitrary gain threshold.','final':'Complete task/shape/basis coverage where needed for changed mapping, strict numerics, mutation/counter/drain checks and current-incumbent whole-policy comparison before promotion.'},
 {'gate':'Profiling and schedule','early':'Finite event timing, same fixtures, simple balanced AB/BA and both signed outcomes. Selected launch identity from existing dispatch/node metadata.','defer_or_remove':'Profiler/Chrome/NCU as optional diagnostics; parser failures invalidate attribution, not already valid numerical outputs. Separate setup smoke from expensive prepare/fullpolicy.','final':'All30 package/selection checks and separate official evaluation when required; retain tiny/conflicting estimates.'}
]}
OUT.write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps({'path':rel(OUT),'sha256':hashlib.sha256(OUT.read_bytes()).hexdigest(),'cases':len(rows)}))
